'use client';

import { useEffect } from 'react';
import { KDSHeader } from '@/modules/kds/components/KDSHeader';
import { KDSFooter } from '@/modules/kds/components/KDSFooter';
import { useKDSStore } from '@/modules/kds/store/kdsStore';
import { useShallow } from 'zustand/react/shallow';
import { useFilterStore } from '@/modules/kds/store/useFilterStore';
import { isKDSModuleActive } from '@/modules/kds/utils/kdsModuleFlags';
import { AlertCircle } from 'lucide-react';
import { OrderTicket } from '@/modules/kds/components/ticket/OrderTicket';
import { useAuth } from '@/app/providers/AuthProvider';

export default function KDSMasterPage() {
    const { addOrUpdateOrder, autoInitNetworkListener } = useKDSStore();
    const { enabledModules } = useAuth();

    const orders = useKDSStore(useShallow((state) => Object.values(state.orders)));
    const hasOrders = orders.length > 0;

    useEffect(() => {
        autoInitNetworkListener();
    }, [autoInitNetworkListener]);

    // Mock Data Initialization
    useEffect(() => {
        if (!hasOrders) {
            // Add some mock orders if empty to showcase the 5-column grid
            const mockOrders = [
                { id: '1', orderNumber: '329', customerName: 'Samir Thai', fulfillment_type: 'PICKUP', createdAt: new Date(Date.now() - 600000).toISOString(), prepTimeMinutes: 15, stage: 'FIRED', isDelayed: true },
                { id: '2', orderNumber: '330', customerName: 'Amazebowls', fulfillment_type: 'PICKUP', createdAt: new Date(Date.now() - 400000).toISOString(), prepTimeMinutes: 10, stage: 'FIRED', isDelayed: false },
                { id: '3', orderNumber: '331', customerName: 'Mama Musubi', fulfillment_type: 'PICKUP', createdAt: new Date(Date.now() - 300000).toISOString(), prepTimeMinutes: 12, stage: 'FIRED', isDelayed: false },
                { id: '4', orderNumber: '332', customerName: 'Bad-Ass Breakfast', fulfillment_type: 'PICKUP', createdAt: new Date(Date.now() - 200000).toISOString(), prepTimeMinutes: 20, stage: 'NEW', isDelayed: false },
                { id: '5', orderNumber: '333465882', customerName: 'The Halal Guys', fulfillment_type: 'PICKUP', createdAt: new Date(Date.now() - 100000).toISOString(), prepTimeMinutes: 15, stage: 'NEW', isDelayed: false },
                { id: '6', orderNumber: '332', customerName: 'Bad-Ass Breakfast', fulfillment_type: 'PICKUP', createdAt: new Date().toISOString(), prepTimeMinutes: 20, stage: 'NEW', isDelayed: false },
            ];

            mockOrders.forEach(o => addOrUpdateOrder({
                ...o,
                updatedAt: new Date().toISOString(),
                items: [
                    { id: o.id + '-1', name: 'Shrimp Dumpling Miso Soup', quantity: 1, modifiers: [], categoryId: 'cat-1' },
                    { id: o.id + '-2', name: 'Real Crab California Roll', quantity: 1, modifiers: [{ name: 'Premium White Rice' }, { name: 'Spicy Mayo' }], categoryId: 'cat-2' },
                    { id: o.id + '-3', name: 'Vegan salad', quantity: 1, modifiers: [], categoryId: 'cat-3' }
                ]
            } as any));
        }
    }, [hasOrders, addOrUpdateOrder]);

    if (!isKDSModuleActive(enabledModules)) {
        return (
            <div className="h-screen w-screen bg-white flex flex-col items-center justify-center p-6 text-center">
                <AlertCircle size={40} className="text-red-500 mb-4" />
                <h1 className="text-2xl font-black text-gray-900 uppercase mb-2">KDS Module Inactive</h1>
            </div>
        );
    }

    return (
        <div className="flex flex-col h-screen overflow-hidden kds-root bg-[#F3F4F6]">
            <KDSHeader />

            <main className="flex-1 overflow-hidden relative">
                <div className="h-full universal-kds-layout">
                    {/* Fixed 5-column grid layout as seen in the image */}
                    <div className="p-4 grid grid-cols-5 gap-4 h-full auto-rows-max overflow-y-auto scrollbar-hide">
                        {orders.map(order => (
                            <div key={order.id} className="h-fit">
                                <OrderTicket orderId={order.id} />
                            </div>
                        ))}
                    </div>
                </div>

                {!hasOrders && (
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                        <span className="text-gray-300 font-black uppercase tracking-[0.4em] text-lg">Waiting for orders</span>
                    </div>
                )}
            </main>

            <KDSFooter />
        </div>
    );
}
